-- Step 1 (generated by Prisma): add the column. It must be nullable — existing rows have no value yet
ALTER TABLE "orders" ADD COLUMN "paid_at" TIMESTAMPTZ(6);

-- Step 2 (by hand): backfill the existing rows. The real payment time was never stored,
-- so created_at is the best approximation we have. Refunded orders were paid too
UPDATE "orders" SET "paid_at" = "created_at" WHERE "status" IN ('paid', 'refunded');

-- Step 3 (by hand): from now on the database guarantees the rule for new rows as well
ALTER TABLE "orders"
    ADD CONSTRAINT "orders_paid_has_paid_at" CHECK ("status" <> 'paid' OR "paid_at" IS NOT NULL),
    ADD CONSTRAINT "orders_pending_has_no_paid_at" CHECK ("status" <> 'pending' OR "paid_at" IS NULL);
